INSERT INTO `products` VALUES (2,'T shirt','this is testing 2',20,'NIKE 1001',599.00,799.00,100,'t45ssdf','active',1,'2025-11-08 06:43:49','2026-08-08 02:49:07',1,0,NULL,NULL,0,'',0,0.00,NULL,0,'in_stock',1,NULL,'<p>Crafted from 100% combed cotton, this custom printed polo t-shirt is designed for maximum comfort and style. Upload your logo or add custom text to personalize for your team, event, or brand.</p>','<p>Machine wash cold with like colors. Do not iron directly on print. Tumble dry low.</p>','<p>Custom printed products ship within 2-3 business days. Delivery in 3-5 days across India.</p>',0,0,0,1,'[{\"label\":\"Chest Logo Upload\",\"type\":\"file\",\"required\":true},{\"label\":\"Custom Name \\/ Text\",\"type\":\"text\",\"required\":false}]','[101]',1,'[\"White\",\"Black\",\"Navy Blue\",\"Rust Brown\"]',NULL,'[\"S\",\"M\",\"L\",\"XL\",\"XXL\"]','[\"100% Cotton 180gsm\",\"Cotton Blend 200gsm\",\"Polyester 160gsm\"]',NULL,NULL,NULL,NULL,1,50.00,99.00,0.00,'','','yes','hours',24,'yes','Custom Printed Men Polo T-Shirt - Printmont',NULL,'Design your own custom printed t-shirt with premium cotton fabric.','',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Need Help?','/contact-us',NULL,0,'',1,1),(4,'Levis Jeans','this is jeans of levis',20,'NIKE22',1299.00,1599.00,100,'WER45WE33','active',1,'2025-11-08 06:51:28','2026-08-08 02:49:07',0,0,0,0,0,'',0,0.00,NULL,0,'in_stock',1,NULL,NULL,NULL,NULL,0,0,0,0,NULL,NULL,0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0.00,0.00,0.00,'','','yes','hours',24,'yes','',NULL,NULL,'',0,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Need Help?','/contact-us',NULL,0,'',1,1),(101,'Wireless Bluetooth Headphones','High-quality wireless headphones with noise cancellation',13,'boat',149.97,NULL,50,'WH-1000XM4','active',0,'2025-11-14 11:38:21','2026-08-08 02:49:07',1,1,NULL,NULL,0,'',0,0.00,NULL,0,'in_stock